"""Processes: every SFW process from the author's earlier studio, with its real status, the models it needs, what opens it here and its cleaned guide. processes.json and processes/<id>.md are generated by scripts/build_processes.py."""
import json, re
from pathlib import Path
from fastapi import APIRouter, HTTPException

HERE = Path(__file__).resolve().parent; DATA = HERE / "processes.json"; DOCS = HERE / "processes"; SAFE = re.compile(r"^[a-z0-9][a-z0-9-]*$")
router = APIRouter()

# No port of the pipeline yet, but its main model has a family page here: open that, marked as the closest thing. Anything else with nothing to open shows as coming soon.
NEAR = {"3d-mesh2photo": ("flux-3-klein", "FLUX.3 Klein"), "3d-motion": ("hy-motion", "HY-Motion"), "3d-retarget-smpl": ("unirig", "UniRig"), "3d-sam3d-body": ("sam-3d-objects", "SAM 3D Objects"), "3d-triposplat": ("triposr", "TripoSR"), "skeleton-from-motion": ("dwpose", "DWPose"), "virtual-set": ("wan2-2", "Wan 2.2"), "world-kit": ("unirig", "UniRig"), "gif-maker": ("rife", "RIFE"), "timelapse": ("qwen-image-2-1", "Qwen-Image 2.1"), "pose-set": ("qwen-image-2-1", "Qwen-Image 2.1"), "fusion-paste": ("qwen-image-2-1", "Qwen-Image 2.1"), "character-faceless-crops": ("flux-1", "FLUX.1"), "song-recreate": ("mini-max-music3", "MiniMax Music 3"), "sound-maker": ("ace-step-1-5", "ACE-Step 1.5"), "watch-video": ("vlm", "Vision models"), "h3-long-prompts": ("minimax-h3", "MiniMax H3"), "h3-purpose-anchors": ("minimax-h3", "MiniMax H3"), "video-wan-decode": ("wan2-1", "Wan 2.1"), "image-dfserve-modes": ("flux-1", "FLUX.1"), "model-lanes": ("flux-3-klein", "FLUX.3 Klein"), "card-actions-remix-variations-retry": ("upscale-models", "Upscale models")}

def load():
    d = json.load(open(DATA, encoding="utf-8"))
    for p in d["processes"]:
        if not p.get("open") and p["id"] in NEAR: p["open"] = {"type": "family", "id": NEAR[p["id"]][0], "label": NEAR[p["id"]][1], "near": True}
    return d

@router.get("/api/processes")
def processes_list(): return load()

@router.get("/api/processes/{pid}/doc")
def process_doc(pid: str):
    if not SAFE.match(pid): raise HTTPException(400, "bad process id")
    row = next((p for p in load()["processes"] if p["id"] == pid), None)
    if not row: raise HTTPException(404, "unknown process")
    if not row["doc"]: raise HTTPException(404, "this guide is not part of this edition")
    return {"id": pid, "name": row["name"], "markdown": (DOCS / f"{pid}.md").read_text(encoding="utf-8")}
